test('document.title restores to app name on unmount when dashboard was loaded directly via URL', async () => {
  // Simulate a fresh page load where the server has already rendered
  // the dashboard name as the document title (e.g., from render_app_template
  // in superset/views/core.py with title=dashboard.dashboard_title).
  document.title = 'Test Dashboard';

  const store = createStore(
    {
      dashboardInfo: { id: 1, metadata: {} },
      dashboardState: { sliceIds: [] },
      dashboardLayout: { past: [], future: [], present: {} },
      nativeFilters: { filters: {} },
      dataMask: {},
    },
    reducerIndex,
  );

  const { unmount } = render(
    <Suspense fallback="loading">
      <DashboardPage idOrSlug="1" />
    </Suspense>,
    { store, useRouter: true },
  );

  await waitFor(() => {
    expect(screen.queryByText('loading')).not.toBeInTheDocument();
  });

  // While mounted, the title should be the dashboard title
  await waitFor(() => expect(document.title).toBe('Test Dashboard'));

  // Unmount the component (simulating navigation away)
  unmount();

  // After unmount, the title should be restored to the app name,
  // not the dashboard name that was captured on mount.
  // The fallback chain is: theme.brandAppName || theme.brandLogoAlt || 'Superset'
  // In tests, the mock theme doesn't have brandAppName/brandLogoAlt, so 'Superset' is expected.
  expect(document.title).toBe('Superset');
});
